/**
 * 50k-row latency micro-benchmark. Gate: p95 <= 40 ms over 200 queries.
 * The fixture DB is generated by eval/fixtures/build.ts --bench (50.000 karar).
 */
import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, statSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { fileURLToPath } from "node:url";
import { Corpus } from "../src/index.ts";
import { buildBenchDb } from "../../../eval/fixtures/build.ts";

const BENCH = fileURLToPath(new URL("../../../eval/fixtures/bench.db", import.meta.url));
const GOLDEN = fileURLToPath(new URL("../../../eval/golden/search.jsonl", import.meta.url));
const BENCH_ADET = 50_000;

let c: Corpus;
let sorular: string[] = [];

function p95(degerler: number[]): number {
  const s = [...degerler].sort((a, b) => a - b);
  return s[Math.max(0, Math.ceil(0.95 * s.length) - 1)]!;
}
function p50(degerler: number[]): number {
  const s = [...degerler].sort((a, b) => a - b);
  return s[Math.floor(0.5 * (s.length - 1))]!;
}

before(() => {
  let yenile = !existsSync(BENCH);
  if (!yenile) yenile = statSync(BENCH).mtimeMs < statSync(GOLDEN).mtimeMs;
  if (!yenile) {
    const db = new DatabaseSync(BENCH, { readOnly: true });
    try {
      const row = db.prepare("SELECT COUNT(*) AS c FROM karar").get() as Record<string, unknown>;
      yenile = Number(row["c"]) !== BENCH_ADET;
    } finally {
      db.close();
    }
  }
  if (yenile) buildBenchDb(BENCH, BENCH_ADET);
  c = new Corpus(BENCH);
  sorular = readFileSync(GOLDEN, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => String((JSON.parse(l) as { sorgu?: string }).sorgu ?? ""))
    .filter(Boolean);
}, { timeout: 120_000 });

after(() => c.close());

test("50k kararda 200 sorgu p95 <= 40 ms", () => {
  assert.equal(sorular.length > 0, true);
  // Warm-up: page cache + statement cache.
  for (let i = 0; i < 10; i++) c.ara({ sorgu: sorular[i % sorular.length]!, limit: 5 });

  const sureler: number[] = [];
  for (let i = 0; i < 200; i++) {
    const t = performance.now();
    c.ara({ sorgu: sorular[i % sorular.length]!, limit: 5 });
    sureler.push(performance.now() - t);
  }
  const p = p95(sureler);
  console.log(
    `[bench] 50k karar / 200 sorgu: p50=${p50(sureler).toFixed(2)} ms p95=${p.toFixed(2)} ms max=${Math.max(...sureler).toFixed(2)} ms`,
  );
  assert.ok(p <= 40, `p95 ${p.toFixed(2)} ms > 40 ms`);
});
